32	function normalizeSingleLine(value: string | null | undefined, maxLength: number): string {
33	  if (!value) {
34	    return ''
35	  }
36	  const normalized = value.trim().replace(/\s+/g, ' ')
37	  if (!normalized) {
38	    return ''
39	  }
40	  if (normalized.length <= maxLength) {
41	    return normalized
42	  }
43	  const body = trimDanglingHighSurrogate(normalized.slice(0, maxLength - 3)).trimEnd()
44	  return `${body}...`
45	}
46	
47	function trimDanglingHighSurrogate(value: string): string {
48	  if (value.length === 0) {
49	    return value
50	  }
51	  const lastCode = value.charCodeAt(value.length - 1)
52	  return lastCode >= 0xd800 && lastCode <= 0xdbff ? value.slice(0, -1) : value
53	}
