 90	function redactValue(value: unknown, seen: WeakSet<object>): unknown {
 91	  if (typeof value !== 'object' || value === null) {
 92	    return value
 93	  }
 94	  if (seen.has(value)) {
 95	    return '[circular]'
 96	  }
 97	  seen.add(value)
 98	  if (Array.isArray(value)) {
 99	    return value.map((entry) => redactValue(entry, seen))
100	  }
101	  return Object.fromEntries(
102	    Object.entries(value).map(([key, entry]) => [
103	      key,
104	      SECRET_KEYS.has(key) ? '[redacted]' : redactValue(entry, seen)
105	    ])
106	  )
107	}
